function downloadSection(lang){const bg=lang==='bg';return `<div class="download-intro"><img src="assets/tasktime.svg" alt="TaskTime" width="72" height="72"><p>${bg?'Избери браузъра, в който работиш. Свали тестовия ZIP пакет и следвай стъпките за ръчно инсталиране. Двата пакета имат една и съща логика.':'Choose the browser you use for work. Download the beta ZIP and follow the manual installation steps. Both packages use the same logic.'}</p></div><div class="cards browser-cards">${['Chrome','Opera'].map(browser=>`<article class="card"><div class="browser-title"><img src="assets/${browser.toLowerCase()}.svg" alt="" width="44" height="44"><div><h3>${browser==='Chrome'?'Google Chrome':'Opera Browser'}</h3><small>DESKTOP · BETA 0.1.2 · ZIP</small></div></div><p>${bg?'Засичане на задачи, смени, сигнали за нова задача и неактивност, личен отчет.':'Task and shift tracking, new-task and idle alerts, personal report.'}</p><a class="download-button" download href="downloads/tasktime-${browser.toLowerCase()}-0.1.2.zip"><span aria-hidden="true">↓</span> ${bg?'Свали за':'Download for'} ${browser}<span class="file-size">~28 KB</span></a><a class="install-link" href="#installation">${bg?'Как се инсталира?':'How do I install it?'} →</a></article>`).join('')}</div><div class="callout beta-notice"><strong>${bg?'Първа тестова версия, не официално издание.':'First beta, not a store release.'}</strong> ${bg?'Пакетите се зареждат ръчно. Засичането е проверено с тестове и пробна страница, но още не напълно в реалните сайтове. Първо сравни пробни записи.':'Packages are loaded manually. Detection is covered by tests and a mock page but not yet fully on the live sites. Compare trial records first.'}</div><div class="release-grid"><div><h3>${bg?'Включено в 0.1.2':'Included in 0.1.2'}</h3><ul><li>${bg?'Задачи от всички лиги под /global-tasks/; екранът за чакане /next не е задача.':'Tasks from every league under /global-tasks/; the /next waiting screen is not a task.'}</li><li>${bg?'Четирите бутона Finish / Clear Samples & Next / Exit приключват задачата.':'All four Finish / Clear Samples & Next / Exit buttons finish a task.'}</li><li>${bg?'🟢 сигнал за нова задача, 🟠/🔴 при „Are you still active?“ — звук, цвят и заглавие на таба.':'🟢 new-task alert, 🟠/🔴 on “Are you still active?” — sound, tab colour and title.'}</li><li>${bg?'Настройки: звук, сила, тест, системно известие (по избор).':'Settings: sound, volume, test, optional system notification.'}</li><li>${bg?'Смени от Ximble: почивки, нощни смени, overtime въпроси.':'Ximble shifts: breaks, overnight shifts, overtime questions.'}</li><li>${bg?'Статистика по тип, преглед на неясни задачи, CSV и JSON архив.':'Statistics by type, review of uncertain tasks, CSV and JSON backup.'}</li></ul></div><div><h3>${bg?'Ограничения на теста':'Beta limitations'}</h3><ul><li>${bg?'Без бутон за край или с пропуск над 45 сек. задачата отива за преглед.':'Without a finish button or with a gap over 45 s a task goes to review.'}</li><li>${bg?'LD и AE (цял мач по линк) още не се обработват отделно.':'LD and AE (whole-match links) are not handled separately yet.'}</li><li>${bg?'Началото на вече започнала смяна не се възстановява назад. Дръж Ximble отворен.':'Earlier time in an already-started shift is not reconstructed. Keep Ximble open.'}</li><li>${bg?'Няма синхронизация, норми, XLSX и възстановяване от JSON.':'No sync, targets, XLSX or JSON restore yet.'}</li></ul></div></div><div id="installation" class="installation"><span class="eyebrow">${bg?'ИНСТАЛИРАНЕ · 5 СТЪПКИ':'INSTALLATION · 5 STEPS'}</span><h3>${bg?'От ZIP до иконка в браузъра':'From ZIP to a browser icon'}</h3><ol><li>${bg?'Свали пакета за своя браузър и го разархивирай в постоянна папка.':'Download your browser’s package and extract it into a permanent folder.'}</li><li>${bg?'Отвори страницата за разширения. Копирай съответния адрес в адресната лента:':'Open the extensions page. Copy the appropriate address into the address bar:'}<div class="browser-addresses"><code>chrome://extensions</code><code>opera://extensions</code></div></li><li>${bg?'Включи Developer mode / Режим за програмисти и избери Load unpacked / Зареждане на разопаковано разширение.':'Enable Developer mode and choose Load unpacked.'}</li><li>${bg?'Избери разархивираната папка, в която се намира manifest.json — не самия ZIP.':'Select the extracted folder containing manifest.json — not the ZIP itself.'}</li><li>${bg?'Закачи иконката TaskTime. Презареди Redstone и Ximble в същия профил. Клик върху иконката отваря отчета.':'Pin TaskTime. Reload Redstone and Ximble in the same profile. Click the icon to open your report.'}</li></ol><p class="caption">${bg?'При обновяване замени файловете в същата папка и натисни Reload на съществуващата добавка. Не я премахвай: това изтрива локалните данни. Първо направи JSON архив.':'To update, replace the files in the same folder and Reload the existing extension. Do not remove it: removal deletes local data. Export a JSON backup first.'}</p><p class="caption">${bg?'Официални инструкции:':'Official instructions:'} <a href="https://developer.chrome.com/docs/extensions/get-started/tutorial/hello-world#load-unpacked" target="_blank" rel="noopener">Chrome</a> · <a href="https://help.opera.com/en/extensions/testing/" target="_blank" rel="noopener">Opera</a></p></div><div class="icon-download"><img src="assets/tasktime.svg" width="60" height="60" alt="TaskTime — clock with checkmark"><div><h3>${bg?'Иконката на TaskTime':'The TaskTime icon'}</h3><p>${bg?'Часовник + отметка: време и завършена задача. Включена е в двата пакета в размери 16, 32, 48 и 128 px.':'Clock + checkmark: time and completed work. Included in both packages at 16, 32, 48 and 128 px.'}</p><a href="assets/tasktime.svg" download>${bg?'Свали SVG':'Download SVG'}</a> · <a href="assets/tasktime-128.png" download>PNG 128 px</a></div></div><p class="caption">${bg?'Всички работни данни остават в браузъра. Няма сървър, аналитика или автоматични действия по задачите. Иконите на браузърите обозначават съвместимост; проектът не е свързан с Google или Opera.':'All work data stays in the browser. No server, analytics or automatic task actions. Browser icons identify compatibility; this project is not affiliated with Google or Opera.'} <a href="downloads/checksums.json">SHA-256</a></p>`}
for(const lang of ['bg','en']){const d=data[lang],bg=lang==='bg';d.badge=bg?'BETA 0.1.2 · ПАКЕТИ ЗА РЪЧНО ИНСТАЛИРАНЕ':'BETA 0.1.2 · MANUAL INSTALLATION PACKAGES';d.aside=bg?'Ръководство · тестова версия 0.1.2.<br>Сайтът не събира работни данни.':'Guide · beta 0.1.2.<br>This website does not collect work data.';d.items.unshift(bg?'Сваляне и инсталиране':'Download & install');d.sections.unshift([bg?'TaskTime за твоя браузър.':'TaskTime for your browser.',downloadSection(lang)]);const last=d.sections.at(-1);last[1]=last[1].replace('Тази страница е спецификация на идеята — самата добавка още не е създадена.','Налична е тестова версия 0.1.2 от секцията за сваляне. Тя покрива основния поток; останалите описани възможности са план и изискват проверка в реалните сайтове.').replace('This page specifies the concept; the extension itself has not been built.','Beta 0.1.2 is available in the download section. It implements the core flow; the broader capabilities remain a plan and require live-site verification.');}
const baseRender=render;render=function(lang){baseRender(lang);const a=document.createElement('a');a.href='#s0';a.className='hero-download';a.textContent=lang==='en'?'↓ Download beta for your browser':'↓ Свали тестовата добавка';document.querySelector('.hero').append(a)};render(document.documentElement.lang);
